param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'calling-conventions-field-metadata-identity-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture




function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}



function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}
function Value($value,$self){if($null -eq $value){return $null};if($value -is [Type]){if([object]::ReferenceEquals($value,$self)){return 'self'};return 'type:'+$value.ToString()};if($value -is [bool]){return $value.ToString().ToLowerInvariant()};if($value -is [Enum]){return ([int]$value).ToString()};if($value -is [Array]){return (($value|ForEach-Object {Value $_ $self})-join ';')};return $value.ToString()}
function Resolve($name){if($name -eq 'GenericListP'){return [object].Assembly.GetType('System.Collections.Generic.List`1').GetGenericArguments()[0]};if($name -eq 'GenericDictP'){return [object].Assembly.GetType('System.Collections.Generic.Dictionary`2').GetGenericArguments()[0]};if($name -eq 'GenericDictQ'){return [object].Assembly.GetType('System.Collections.Generic.Dictionary`2').GetGenericArguments()[1]};if($name -eq 'SigListArray'){return (Resolve 'SigList').MakeArrayType()};if($name -eq 'SigListRef'){return (Resolve 'SigList').MakeByRefType()};if($name -eq 'SigEmpty'){return [Type]::MakeGenericSignatureType([object].Assembly.GetType('System.Collections.Generic.List`1'),[Type[]]::new(0))};if($name.Contains('@')){$parts=$name.Split('@');$value=Resolve $parts[0];switch($parts[1]){'sz'{return $value.MakeArrayType()};'rank'{return $value.MakeArrayType(2)};'ptr'{return $value.MakePointerType()};'ref'{return $value.MakeByRefType()}}};if($name -eq 'NullableInt'){return [object].Assembly.GetType('System.Nullable`1').MakeGenericType([Type[]]@([int]))};$list=[object].Assembly.GetType('System.Collections.Generic.List`1');$dict=[object].Assembly.GetType('System.Collections.Generic.Dictionary`2');$nullable=[object].Assembly.GetType('System.Nullable`1');switch($name){'null'{return $null};'ListD'{return $list};'DictD'{return $dict};'NullableD'{return $nullable};'TupleD'{return [object].Assembly.GetType('System.ValueTuple`2')};'ListS'{return $list.MakeGenericType([type[]]@([string]))};'Sig0'{return [Type]::MakeGenericMethodParameter(0)};'Sig1'{return [Type]::MakeGenericMethodParameter(1)};'Sig0Array'{return [Type]::MakeGenericMethodParameter(0).MakeArrayType()};'Sig0Ref'{return [Type]::MakeGenericMethodParameter(0).MakeByRefType()};'SigList'{return [Type]::MakeGenericSignatureType($list,[type[]]@([Type]::MakeGenericMethodParameter(0)))};default{return [Type]::GetType('System.'+$name,$true,$false)}}}
function ResolveMember($name){if($name -eq 'Null'){return $null};$parts=$name.Split(':');$type=$null;if($parts[1] -eq 'ListI'){$type=(Resolve 'ListD').MakeGenericType([Type[]]@([int]))}else{$type=Resolve $parts[1]};switch($parts[0]){'F'{return $type.GetField($parts[2],$(if($parts[2] -eq 'm_value'){[Reflection.BindingFlags]'NonPublic,Instance'}else{[Reflection.BindingFlags]'Public,NonPublic,Instance,Static'}))};'M'{return $type.GetMethod($parts[2])};'T'{return $type};'P'{return $type.GetDefaultMembers()[0]};default{throw 'unknown member'}}}
function Label($member){if($null -eq $member){return $null};return $member.Name+'#'+$member.DeclaringType.FullName+'#'+([int]$member.MemberType)}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new()
foreach($case in $plan.cases){$type=Resolve $case.type;$member=ResolveMember $case.member;$other=ResolveMember $case.other;$value=$null;$errorName='none';$message=$null;$hResult=0;$param=$null;$same=$false;try{switch($case.route){'Lookup'{$result=$type.GetMemberWithSameMetadataDefinitionAs($member);$value=Label $result;$same=[object]::ReferenceEquals($result,$member)};'Same'{$value=$member.HasSameMetadataDefinitionAs($other).ToString().ToLowerInvariant()};'Snapshot'{$flags=[Enum]::ToObject([Reflection.BindingFlags],[int]$case.flags);$first=$type.GetFields($flags);$second=$type.GetFields($flags);$arrays=[object]::ReferenceEquals($first,$second);$descriptors=$true;$named=$true;$isolation=$true;for($i=0;$i -lt $first.Length;$i++){$descriptors=$descriptors -and [object]::ReferenceEquals($first[$i],$second[$i]);$named=$named -and [object]::ReferenceEquals($first[$i],$type.GetField($first[$i].Name,$flags))};if($first.Length -gt 0){$expected=$first[0];$first[0]=$null;$third=$type.GetFields($flags);$isolation=[object]::ReferenceEquals($second[0],$expected) -and [object]::ReferenceEquals($third[0],$expected)};$value=$arrays.ToString().ToLowerInvariant()+'|'+$descriptors.ToString().ToLowerInvariant()+'|'+$named.ToString().ToLowerInvariant()+'|'+$isolation.ToString().ToLowerInvariant()};default{throw 'unknown route'}}}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};$errorName=$errorValue.GetType().FullName;$message=$errorValue.Message;$hResult=$errorValue.HResult;if($errorValue -is [ArgumentException]){$param=$errorValue.ParamName}};$rows.Add([ordered]@{id=$case.id;valueUnits=(Units $value);exception=$errorName;messageUnits=(Units $message);hResult=$hResult;paramUnits=(Units $param);same=$same})}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS metadata member lookup capture: $($rows.Count) calls"
